export default{cssContent:"/*\n * Copyright 2023 The Chromium Authors. All rights reserved.\n * Use of this source code is governed by a BSD-style license that can be\n * found in the LICENSE file.\n */\n:root {\n  --icon-action: var(--color-primary-bright);\n  --icon-arrow-main-thread: var(--color-primary-bright);\n  --icon-checkmark-green: var(--color-tertiary-bright);\n  --icon-checkmark-purple: var(--color-purple-bright);\n  --icon-checkmark-red: var(--color-error-bright);\n  --icon-contrast-issue: var(--color-error-bright);\n  --icon-default: var(--sys-color-on-surface-subtle);\n  --icon-default-hover: var(--color-on-surface);\n  --icon-disabled: color-mix(in sRGB, var(--color-on-surface-variant) 55%, transparent);\n  --icon-error: var(--color-error-bright);\n  --icon-file-authored: var(--color-orange-bright);\n  --icon-file-default: var(--color-on-surface-variant);\n  --icon-file-document: var(--color-primary-bright);\n  --icon-file-font: var(--color-turqoise-bright);\n  --icon-file-image: var(--color-tertiary-bright);\n  --icon-file-script: var(--color-orange-bright);\n  --icon-file-styles: var(--color-purple-bright);\n  --icon-fold-marker: var(--color-on-surface-variant);\n  --icon-folder-authored: var(--color-orange);\n  --icon-folder-primary: var(--color-on-surface-variant);\n  --icon-folder-deployed: var(--color-primary-bright);\n  --icon-folder-workspace: var(--color-orange);\n  --icon-force-white: var(--sys-color-on-tonal-container);\n  --icon-gap-focus-selected: var(--sys-color-tonal-container);\n  --icon-gap-default: var(--sys-color-cdt-base-container);\n  --icon-gap-inactive: var(--sys-color-neutral-container);\n  --icon-gap-hover: var(--sys-color-state-hover-on-subtle);\n  --icon-gap-toolbar: var(--sys-color-surface1);\n  --icon-gap-toolbar-hover: var(--sys-color-state-header-hover);\n  --icon-info: var(--color-primary-bright);\n  --icon-link: var(--color-primary-bright);\n  --icon-no-request: var(--color-orange-bright);\n  --icon-primary: var(--color-primary-bright);\n  --icon-record: var(--color-error-bright);\n  --icon-request-response: var(--color-primary-bright);\n  --icon-request: var(--color-on-surface-variant);\n  --icon-security-lock: var(--color-tertiary-bright);\n  --icon-css: var(--sys-color-purple-bright);\n  --icon-css-hover: var(--sys-color-purple);\n  --icon-status-code-ok: var(--color-tertiary-bright);\n  --icon-stop: var(--color-error-bright);\n  --icon-toggled: var(--color-primary-bright);\n  --icon-warning: var(--color-orange-bright);\n  --ui-text: var(--sys-color-on-surface-subtle);\n  --text-disabled: var(--ref-palette-neutral60);\n  --text-primary: var(--sys-color-on-surface);\n  --text-secondary: var(--sys-color-token-subtle);\n  --text-link: var(--sys-color-primary);\n  --text-selection: var(--sys-color-state-ripple-primary);\n  --color-grid-stripe: var(--sys-color-surface1);\n  --color-grid-default: var(--sys-color-surface);\n  --color-grid-focus-selected: var(--sys-color-tonal-container);\n  --color-grid-selected: var(--sys-color-neutral-container);\n  --color-grid-hovered: var(--sys-color-state-hover-on-subtle);\n}\n"};